        if '<html' in txt.lower() or '<div' in txt.lower(): txt=re.sub('<[^>]+>',' ',txt); txt=html.unescape(txt)
        # strip quoted
        lines=[l for l in txt.splitlines() if not l.startswith('>')]
        print('\n'.join(lines)[:int(sys.argv[2]) if len(sys.argv)>2 else 4000])
f=sys.argv[1]
